import {companionArtSvg} from './companion-art.mjs';
import {getCompanionAbility} from './companion-abilities.mjs';
import {SKILLS,MAIN_WISP_BRANCHES,getSkillCost,getSkillLockReason,isSkillRevealed,canChooseStartingSkill} from './model.mjs?v=rest-trees-collector-1';
import {skillIcon} from './upgrade-icons.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mainWispTreeMarkup({run,wallet,canBuy,selected='main-sight'}){
 const initial=canChooseStartingSkill(run),roots=MAIN_WISP_BRANCHES.map(x=>x.root),skill=SKILLS[selected]||SKILLS['main-sight'];
 const owned=(wallet.skills[skill.id]||0)>=(skill.maxRank||1),free=initial&&roots.includes(skill.id),reason=owned?'Learned':getSkillLockReason(wallet,skill.id),cost=getSkillCost(wallet,skill.id);
 const learnable=!owned&&(free||canBuy&&!reason&&cost!==null&&wallet.embers>=cost);
 const node=id=>{const s=SKILLS[id],learned=!!wallet.skills[id],locked=!!getSkillLockReason(wallet,id)&&!learned;return `<button class="wisp-tree-node ${learned?'learned':''} ${selected===id?'inspected':''} ${locked?'sealed':''}" data-action="inspect-main-skill" data-id="${id}" aria-label="Inspect ${esc(s.name)}${learned?', learned':''}" aria-pressed="${selected===id}">${skillIcon(s)}<span>${esc(s.name)}</span><small>${learned?'LEARNED':initial&&roots.includes(id)?'FREE GIFT':locked?'SEALED':''}</small></button>`};
 return `<div class="tree-heading"><h2>Main wisp</h2><span class="ember-wallet">${Math.floor(wallet.embers||0)} EMBERS</span></div><div class="tree-tabs"><button class="selected" data-action="tree-branch" data-id="main">Main wisp</button>${run.companions.map(id=>`<button data-action="tree-branch" data-id="${id}">${companionArtSvg(id)}<span>${getCompanionAbility(id).name}</span></button>`).join('')}${wallet.afterglowUnlocked?'<button data-action="tree-branch" data-id="afterglow">Afterglow</button>':''}</div><p class="wisp-tree-hint">${initial?'Choose your first gift. Free for this run.':'Follow a branch. Choose one fork on each path.'}</p><div class="wisp-branch-tree"><div class="wisp-tree-origin" aria-hidden="true">✦</div><div class="wisp-tree-lanes">${MAIN_WISP_BRANCHES.map(branch=>`<section class="wisp-tree-lane">${node(branch.root)}<div class="wisp-tree-fork">${branch.leaves.map(node).join('')}</div>${branch.root==='main-efficiency'&&isSkillRevealed(wallet,'main-spare-spark')?`<div class="wisp-life-path"><small>MORE LIVES</small>${node('main-spare-spark')}${isSkillRevealed(wallet,'main-deep-reserve')?node('main-deep-reserve'):''}</div>`:''}</section>`).join('')}</div></div><section class="wisp-node-detail"><div>${skillIcon(skill)}<h3>${esc(skill.name)}</h3></div><p>${esc(skill.description)}</p>${skill.choiceGroup?'<small>One fork per path for this run.</small>':''}<button class="${learnable?'primary':'secondary'}" data-action="${free?'choose-start-skill':'buy-skill'}" data-id="${skill.id}" ${learnable?'':'disabled'}>${owned?'LEARNED':free?'CHOOSE GIFT':reason?esc(reason):!canBuy?'LEARN AT A REST':`LEARN · ${cost} EMBERS`}</button></section>${isSkillRevealed(wallet,'main-bond')?`<div class="wisp-bond-entry">${node('main-bond')}<small>Add a companion slot</small></div>`:''}<div class="wisp-tree-actions"><button class="secondary" data-action="companions">Companions</button><button class="primary" data-action="close-sheet">Done</button></div>`;
}
